create or replace function public.player_combat_loadout_bootstrap(p_channel text,p_legacy_embryo text,p_legacy_moves jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());profile private.player_art_profiles;p private.player_progression_states;m text;moves jsonb:='[]'::jsonb;begin if uid is null then raise exception '需要重新登入';end if;if p_channel not in('formal','test') or jsonb_typeof(coalesce(p_legacy_moves,'[]'))<>'array' then raise exception '招式資料不正確';end if;perform pg_advisory_xact_lock(hashtext(uid::text||'-combat-loadout-'||p_channel));select * into profile from private.player_art_profiles where user_id=uid and channel=p_channel for update;select * into p from private.player_progression_states where user_id=uid and channel=p_channel;if profile.user_id is null or p.user_id is null then raise exception '伺服器戰鬥配置尚未建立';end if;if not profile.combat_imported then profile.sword_embryo:=case when p_legacy_embryo in('heavy','spirit','shadow') and p.sword_path_opened then p_legacy_embryo else '' end;for m in select value#>>'{}' from jsonb_array_elements(coalesce(p_legacy_moves,'[]')) loop exit when jsonb_array_length(moves)>=2;if not moves?m and private.combat_move_allowed(uid,p_channel,m,p,profile) then moves:=moves||jsonb_build_array(m);end if;end loop;if jsonb_array_length(moves)=0 then if p.spirit_path_opened then moves:='["origin"]';elsif p.body_path_opened then moves:='["body-origin"]';elsif profile.sword_embryo<>'' then moves:=jsonb_build_array(profile.sword_embryo||case profile.sword_embryo when 'heavy' then '-fall' when 'spirit' then '-thread' else '-stars' end);end if;end if;update private.player_art_profiles set sword_embryo=profile.sword_embryo,combat_moves=moves,combat_imported=true,revision=revision+1,updated_at=now() where user_id=uid and channel=p_channel returning * into profile;update private.player_cave_states set has_sword_embryo=profile.sword_embryo<>'' where user_id=uid and channel=p_channel;end if;return private.combat_loadout_snapshot(profile);end $$;
